text:
{
 "title": "相続土地国庫帰属法",
 "lead": {
  "es": "親《おや》などからうけついだ土地《とち》を、決《き》まった条件《じょうけん》で国《くに》に引《ひ》きとってもらえるしくみをつくった法律《ほうりつ》です。",
  "hs": "相続などで受けついだ土地を、法務大臣の承認を受けて国のものにできるしくみをつくった法律です。",
  "std": "所有者不明土地の発生を抑えるため、相続等で取得した土地の所有権を、法務大臣の承認を受けて国庫に帰属させる制度を創設する法律です。",
  "univ": "相続等による所有者不明土地の発生の抑制を図るため、相続等により土地の所有権を取得した者が、法務大臣の承認を受けてその土地の所有権を国庫に帰属させることができる制度を創設する法律。"
 },
 "facts": [
  {
   "es": "相続《そうぞく》（または相続人《そうぞくにん》へのいぞう）で土地《とち》を受《う》けついだ人《ひと》などは、その土地《とち》を国《くに》のものにしてほしいと、法務大臣《ほうむだいじん》に申《もう》しこめます。建物《たてもの》がある土地《とち》などはのぞきます。",
   "hs": "相続や、相続人への｜遺贈《いぞう》で土地の所有権や共有持分を受けついだ人などは、その土地（建物がある土地などをのぞく）を国のものにすることの承認を、法務大臣に求められる。",
   "std": "相続又は相続人に対する遺贈で土地の所有権又は共有持分を取得した者等は、その土地（建物の存する土地等を除く）の所有権を国庫に帰属させることの承認を法務大臣に求めることができます。",
   "univ": "相続又は遺贈（相続人に対する遺贈に限る。）により土地の所有権又は共有持分を取得した者等は、法務大臣に対し、その土地（建物の存する土地であるもの等を除く。）の所有権を国庫に帰属させることについての承認を求めることができる。"
  },
  {
   "es": "法務大臣《ほうむだいじん》は、管理《かんり》や処分《しょぶん》にとても多《おお》くのお金《かね》や手間《てま》がかかる土地《とち》でなければ、みとめなければなりません。",
   "hs": "法務大臣は、その土地が、ふつうの管理や処分に多すぎる費用や労力がかかる土地でないと認めるときは、承認しなければならない。",
   "std": "法務大臣は、対象の土地が、通常の管理・処分に過分の費用又は労力を要する土地に該当しないと認めるときは、承認しなければなりません。",
   "univ": "法務大臣は、承認の対象となる土地が、通常の管理又は処分をするに当たり過分の費用又は労力を要する土地に該当しないと認めるときは、その土地の所有権の国庫への帰属についての承認をしなければならない。"
  },
  {
   "es": "法務大臣《ほうむだいじん》は、調《しら》べる必要《ひつよう》があるときは、職員《しょくいん》に調《しら》べさせることができます。",
   "hs": "法務大臣は、｜審査《しんさ》に必要なときは、職員に事実を調査させることができ、調査の権限について定める。",
   "std": "法務大臣は、承認の審査に必要があると認めるときは職員に事実の調査をさせることができ、調査権限に関する規定を設けます。",
   "univ": "法務大臣は、承認に係る審査をするため必要があると認めるときは、その職員に事実の調査をさせることができるとともに、調査権限に関する規定を設ける。"
  },
  {
   "es": "うそなどの不正《ふせい》でみとめてもらったとわかったときは、みとめたことを取《と》り消《け》せます。引《ひ》きとれない土地《とち》だったことで国《くに》に損《そん》が出《で》たときは、申《もう》しこんだ人《ひと》が国《くに》にはらう決《き》まりもつくります。",
   "hs": "うそなど不正な手段で承認を受けたとわかったときの承認の取消しや、承認のときに承認できない土地にあたる理由があったために国に損害が生じたときの、｜申請《しんせい》した人の損害｜賠償《ばいしょう》責任について定める。",
   "std": "偽りその他不正の手段で承認を受けたことが判明した場合の承認の取消しと、承認時に対象土地が承認できない土地に該当する事由があったことで国に損害が生じた場合の承認申請者の損害賠償責任について規定を設けます。",
   "univ": "承認申請者が偽りその他不正の手段によって承認を受けたことが判明した場合における承認の取消しに関する規定を設けるとともに、承認の時において対象土地が過分の費用又は労力を要する土地に該当する事由があったことによって国に損害が生じた場合における承認申請者の国に対する損害賠償責任に関する規定を設ける。"
  },
  {
   "es": "この法律《ほうりつ》は、出《だ》された日《ひ》から2年《ねん》をこえない日《ひ》のうち、政府《せいふ》が決《き》める日《ひ》から使《つか》われます。",
   "hs": "この法律は、公布の日から2年をこえない｜範囲《はんい》で政令で定める日から｜施行《しこう》する。",
   "std": "公布の日から起算して2年を超えない範囲内で政令で定める日から施行します。",
   "univ": "この法律は、公布の日から起算して2年を超えない範囲内において政令で定める日から施行する。"
  }
 ]
}
